-- MATOS NEGÓCIOS IMOBILIÁRIOS — V10.14.2\n-- Correção de permissões do proprietário e carregamento da equipe.\n\n-- 1) Proprietário nunca perde as permissões padrão por sobrescritas personalizadas.\nupdate public.organization_members\nset permissions = '{}'::jsonb,\n    updated_at = now()\nwhere role = 'owner';\n\ncreate or replace function public.effective_permissions_json()\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case\n    when m.role = 'owner' then public.role_permissions_json('owner')\n    else coalesce(public.role_permissions_json(m.role), '{}'::jsonb) || coalesce(m.permissions, '{}'::jsonb)\n  end\n  from public.organization_members m\n  where m.user_id = auth.uid()\n    and m.status = 'active'\n  order by case m.role when 'owner' then 1 when 'admin' then 2 when 'broker' then 3 else 4 end,\n           m.created_at\n  limit 1;\n$$;\n\ngrant execute on function public.effective_permissions_json() to authenticated;\n\ncreate or replace function public.current_access_context()\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'organization_id', m.organization_id,\n    'organization_name', o.name,\n    'organization_slug', o.slug,\n    'plan_code', o.plan_code,\n    'user_id', p.id,\n    'full_name', p.full_name,\n    'email', p.email,\n    'role', m.role,\n    'status', m.status,\n    'permissions', case\n      when m.role = 'owner' then public.role_permissions_json('owner')\n      else public.role_permissions_json(m.role) || coalesce(m.permissions, '{}'::jsonb)\n    end\n  )\n  from public.organization_members m\n  join public.organizations o on o.id = m.organization_id\n  join public.profiles p on p.id = m.user_id\n  where m.user_id = auth.uid()\n    and m.status = 'active'\n  order by case m.role when 'owner' then 1 when 'admin' then 2 when 'broker' then 3 else 4 end,\n           m.created_at\n  limit 1;\n$$;\n\ngrant execute on function public.current_access_context() to authenticated;\n\n-- 2) Função segura para listar toda a equipe da organização atual.\n-- Evita depender de joins do PostgREST sujeitos a políticas/RLS e nomes de FK.\ncreate or replace function public.organization_team_members()\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select coalesce(\n    jsonb_agg(\n      jsonb_build_object(\n        'id', m.id,\n        'organization_id', m.organization_id,\n        'user_id', m.user_id,\n        'role', m.role,\n        'status', m.status,\n        'permissions', coalesce(m.permissions, '{}'::jsonb),\n        'invited_at', m.invited_at,\n        'joined_at', m.joined_at,\n        'created_at', m.created_at,\n        'updated_at', m.updated_at,\n        'profile', jsonb_build_object(\n          'id', p.id,\n          'full_name', p.full_name,\n          'email', p.email,\n          'last_seen_at', p.last_seen_at\n        )\n      )\n      order by\n        case m.role when 'owner' then 1 when 'admin' then 2 when 'broker' then 3 else 4 end,\n        m.created_at\n    ),\n    '[]'::jsonb\n  )\n  from public.organization_members m\n  join public.profiles p on p.id = m.user_id\n  where m.organization_id = public.current_organization_id()\n    and public.has_permission('team.view');\n$$;\n\ngrant execute on function public.organization_team_members() to authenticated;\n\n-- 3) Usuários que já aceitaram convite ficam marcados como ativos/ingressados.\nupdate public.organization_members m\nset status = 'active',\n    joined_at = coalesce(m.joined_at, u.created_at),\n    updated_at = now()\nfrom auth.users u\nwhere u.id = m.user_id\n  and u.last_sign_in_at is not null\n  and m.status <> 'disabled';\n